REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'rule_export_header', '{\"cn\":{\"*告警规则名称\":\"告警规则名称(必填) \\n示例: cpuAlert\",\"*运算表达式\":\"运算表达式(必填) \\n示例: 100-(avg(irate(node_cpu_seconds_total{mode=\'idle\'}[5m])) by(instance)* 100)\",\"*比较符号\":\"比较符号(必填) 可选: >,<,<=,>=,==,!= \\n示例: >\",\"*阈值\":\"阈值(必填) \\n示例: 10\",\"*单位\":\"单位(必填) 可选: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\n示例: short\",\"*持续时间\":\"持续时间(必填),默认单位（秒） \\n示例:60\",\"*告警级别\":\"告警级别(必填) 可选 P1、P2、P3 \\n示例: P1\",\"*告警摘要\":\"告警摘要(必填) \\n示例: cpu告警\",\"告警详细描述\":\"告警详细描述 \\n示例: cpu使用率超过10%的告警规则\",\"告警通知人\":\"告警通知人，多个使用逗号分隔 \\n示例: admin / admin,root\",\"通知方式\":\"告警通知方式，告警通知人不为空时，必填.多个使用逗号分隔 \\n示例: email / email,telephone\",\"告警状态\":\"告警状态，默认开启 开启：1 关闭：0 \\n示例:1\"},\"en\":{\"*AlertName\":\"Alert rule name (required) \\nExample: cpuAlert\",\"*Expr\":\"Operation expression (required) \\nExample: 100-(avg(irate(node_cpu_seconds_total{mode=\'idle\')[5m])) by(instance)* 100)\",\"*Operator\":\"Operation symbol (required) Optional: >,<,<=,>=,==,!= \\nExample:>\",\"*Threshold\":\"Threshold (required) \\nExample: 10\",\"*Unit\":\"Unit (required) Optional: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\nExample:short\",\"*Last\":\"Last (required), the default unit (seconds) \\nExample: 60\",\"*Severity\":\"Alert severity (required) optional P1, P2, P3 \\nExample: P1\",\"*Summary\":\"Alert summary \\nExample: Cpu warning\",\"Description\":\"Alert description \\nExample: Alarm rule for cpu usage exceeding 10%\",\"Receiver\":\"Alert receiver, separated by commas \\nExample: admin / admin,root\",\"Notification method\":\"Alarm notification method. When the receiver is not empty, it is required. Multiple use commas to separate \\nExample: email / email,telephone\",\"State\":\"Alarm status, the default enablement: 1 Close: 0 \\nExample: 1\"}}', 1, NULL);
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'cortex_yml_tmpl', '{\r\n  \"auth_enabled\": false,\r\n  \"server\": {\r\n    \"http_listen_port\": <#if port?default(\"\")?trim?length gt 0> ${port?c} <#else>10093</#if>,\r\n	\"grpc_listen_port\":10094,\r\n    \"grpc_server_max_recv_msg_size\": 104857600,\r\n    \"grpc_server_max_send_msg_size\": 104857600,\r\n    \"grpc_server_max_concurrent_streams\": 1000\r\n  },\r\n  \"distributor\": {\r\n    \"shard_by_all_labels\": true,\r\n    \"pool\": {\r\n      \"health_check_ingesters\": true\r\n    }\r\n  },\r\n  \"ingester_client\": {\r\n    \"grpc_client_config\": {\r\n      \"max_recv_msg_size\": 104857600,\r\n      \"max_send_msg_size\": 104857600,\r\n      \"grpc_compression\": \"gzip\"\r\n    }\r\n  },\r\n  <#if isMemberlistStore>\r\n	\"ingester\": {\r\n		\"lifecycler\": {\r\n		  \"join_after\": \"10s\",\r\n		  \"min_ready_duration\": \"0s\",\r\n		  \"final_sleep\": \"5s\",\r\n		  \"num_tokens\": 512,\r\n		  \"ring\": {\r\n			\"kvstore\": {\r\n			  \"store\": \"memberlist\"\r\n			},\r\n			\"replication_factor\": 1\r\n		  }\r\n		}\r\n	  },\r\n	  \"memberlist\": {\r\n		\"bind_port\": <#if gossIp?default(\"\")?trim?length gt 0>${gossIp?c}<#else>7946</#if>,\r\n		\"join_members\": [\r\n			<#list joinMemberList as joinIp>\r\n				\"${joinIp}:<#if gossIp?default(\"\")?trim?length gt 0>${gossIp?c}<#else>7946</#if>\"\r\n			<#sep>,</#sep>\r\n			</#list>\r\n		],\r\n		\"abort_if_cluster_join_fails\": false\r\n	  },\r\n  <#else>\r\n	  \"ingester\": {\r\n			\"lifecycler\": {\r\n			  \"join_after\": \"10s\",\r\n			  \"min_ready_duration\": \"0s\",\r\n			  \"final_sleep\": \"5s\",\r\n			  \"num_tokens\": 512,\r\n			  \"ring\": {\r\n				\"kvstore\": {\r\n				  \"store\": \"inmemory\"\r\n				},\r\n				\"replication_factor\": 1\r\n			  }\r\n			}\r\n		  },\r\n  </#if>\r\n  \r\n  \"storage\": {\r\n    \"engine\": \"blocks\"\r\n  },\r\n  \"blocks_storage\": {\r\n    \"tsdb\": {\r\n      \"dir\": \"/opt/nezha/cortex/tsdb\"\r\n    },\r\n    \"bucket_store\": {\r\n      \"sync_dir\": \"/opt/nezha/cortex/tsdb-sync\"\r\n    },\r\n	<#if isLocalStorage>\r\n		\"backend\": \"filesystem\",\r\n		\"filesystem\": {\r\n		  \"dir\": \"/opt/nezha/cortex/data/tsdb\"\r\n		}\r\n	<#else>\r\n		\"backend\": \"s3\",\r\n		\"s3\": {\r\n		  \"endpoint\": \"${objectStroageUrl}\",\r\n		  \"bucket_name\": \"${bucketName}\",\r\n		  \"access_key_id\": \"${accessKey}\",\r\n		  \"secret_access_key\": \"${secret}\",\r\n		  \"insecure\": <#if insecure?default(\"\")?trim?length gt 0>${insecure}<#else>true</#if>\r\n		}\r\n	</#if>\r\n  },\r\n  \"store_gateway\": {\r\n    \"sharding_enabled\": true,\r\n    \"sharding_ring\": {\r\n      \"kvstore\": {\r\n        \"store\": <#if isMemberlistStore> \"memberlist\" <#else> \"inmemory\" </#if>\r\n      }\r\n    }\r\n  },\r\n  \"compactor\": {\r\n    \"data_dir\": \"/opt/nezha/cortex/compactor\",\r\n    \"sharding_ring\": {\r\n      \"kvstore\": {\r\n        \"store\": <#if isMemberlistStore> \"memberlist\" <#else> \"inmemory\" </#if>\r\n      }\r\n    }\r\n  },\r\n  \"frontend_worker\": {\r\n    \"match_max_concurrent\": true\r\n  },\r\n  \r\n  <#if isAlert>\r\n	  \"ruler\": {\r\n		\"enable_api\": true,\r\n		\"enable_sharding\": true,\r\n		\"rule_path\": \"/opt/nezha/cortex/rules\",\r\n		\"ring\": {\r\n		  \"num_tokens\": 512,\r\n		  \"kvstore\": {\r\n			\"store\": <#if isMemberlistStore> \"memberlist\" <#else> \"inmemory\" </#if>\r\n		  }\r\n		},\r\n		\"alertmanager_url\":\"http://${systemConfig.alert_api}${systemConfig.alert_path_prefix}\"\r\n	  },\r\n	  \"ruler_storage\":{\r\n		 \"backend\":\"local\",\r\n		 \"local\":{\r\n		   \"directory\":\"/opt/nezha/cortex/rules\"\r\n		 }\r\n	  },\r\n  </#if>\r\n  \"limits\":{\r\n	\"max_series_per_metric\": 500000000\r\n  },\r\n  \"api\":{\r\n     \"alertmanager_http_prefix\":\"/\"\r\n  }\r\n}', 1, 'cortex.yml 配置文件模板');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'prom_yml_tmpl', '{\r\n    \"global\": {\r\n        \"scrape_interval\": \"${scrape_interval}s\",\r\n        \"scrape_timeout\": 	<#if scrape_timeout??> \r\n								\"${scrape_timeout}s\",\r\n						    <#else>\r\n								\"10s\",\r\n							</#if>\r\n        \"evaluation_interval\": \"${scrape_interval}s\"\r\n    },\r\n	\r\n	<#-- alert 配置 -->\r\n	<#if isAlert>\r\n	\"alerting\": {\r\n		\"alertmanagers\": [{\r\n			\"path_prefix\": \"${path_prefix}\",\r\n			\"static_configs\": [{\r\n				\"targets\": [\"${alert_url}\"]\r\n			}]\r\n		}],\r\n		\"alert_relabel_configs\": [{\r\n			\"regex\": \"instance\",\r\n			\"action\": \"labeldrop\"\r\n		}, {\r\n			\"regex\": \"replica\",\r\n			\"action\": \"labeldrop\"\r\n		}]\r\n	},\r\n	\"rule_files\": [\"rule.yml\"],\r\n	</#if>\r\n	\r\n	\r\n	\r\n	<#-- per-datacenter 配置 -->\r\n	<#if !isGlobal>\r\n    \"scrape_configs\": [\r\n	<#list jobList as jobPojo>\r\n			{\r\n			   \"job_name\": \"${jobPojo.job_name}\",\r\n				\"metrics_path\": <#if jobPojo.metrics_path?default(\"\")?trim?length gt 0>\r\n									\"${jobPojo.metrics_path}\",\r\n								<#else>\r\n									\"/metrics\",\r\n								</#if>\r\n				\"static_configs\":[\r\n					<#list jobPojo.staticConfigList as staticConf >\r\n						{\r\n						  \"targets\": [\r\n								<#list staticConf.targets as targetConf>\r\n										\"${targetConf}\"<#sep>,</#sep>\r\n								</#list>\r\n							]\r\n						<#if staticConf.labels ??&& (staticConf.labels?size >0)>\r\n						   ,\r\n						   \"labels\": {\r\n								<#list staticConf.labels?keys as itemKey>\r\n									\"${itemKey}\":<#if staticConf.labels[itemKey]?default(\"\")?trim?length gt 0>\r\n													\"${staticConf.labels[itemKey]}\"\r\n												  <#else>\"\"</#if><#sep>,</#sep>\r\n								</#list>\r\n							} \r\n						</#if>\r\n						}<#sep>,</#sep>\r\n					</#list>\r\n					],\r\n				\"relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					},\r\n					<#if jobPojo.instanceRelabel> \r\n					{\r\n						\"source_labels\": [\r\n						  \"instance\"\r\n						],\r\n						\"regex\": \"(.+)\",\r\n						\"target_label\": \"target\"\r\n					}\r\n					<#else>\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					</#if>\r\n				],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					},\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n				]\r\n			}<#sep>,</#sep>\r\n		</#list>\r\n		<#if jobList??&&(jobList?size>0)>\r\n		,\r\n		</#if>\r\n		<#list endpointList as endpoint>\r\n			{\r\n				\"job_name\": ${endpoint.id?c},\r\n				\"metrics_path\": <#if endpoint.config.metrics_path?default(\"\")?trim?length gt 0>\r\n									\"${endpoint.config.metrics_path}\",\r\n								<#else>\r\n									<#if endpoint.config.protocol == \"http\">\r\n										\"/metrics\",\r\n									<#else>\r\n										\"/snmp\",\r\n									</#if>\r\n								</#if>\r\n				\"scrape_interval\": 	<#if endpoint.config.scrape_interval?default(\"\")?trim?length gt 0>\r\n										\"${endpoint.config.scrape_interval}s\",\r\n									<#else>\r\n										\"${scrape_interval}s\",\r\n									</#if>\r\n				\"scrape_timeout\": 	<#if endpoint.config.scrape_timeout?default(\"\")?trim?length gt 0>\r\n										\"${endpoint.config.scrape_timeout}s\",\r\n									<#else>\r\n										<#if scrape_timeout??> \r\n											\"${scrape_timeout}s\",\r\n										<#else>\r\n											\"10s\",\r\n										</#if>\r\n									</#if>\r\n\r\n\r\n\r\n				<#if endpoint.config.basic_auth??&& (endpoint.config.basic_auth?size >0)>\r\n					<#if endpoint.config.basic_auth.username?default(\"\")?trim?length gt 0 && endpoint.config.basic_auth.password?default(\"\")?trim?length gt 0>\r\n					\"basic_auth\":{\r\n						\"username\": \"${endpoint.config.basic_auth.username}\",\r\n						\"password\": \"${endpoint.config.basic_auth.password}\"\r\n						},\r\n					</#if>\r\n				</#if>\r\n				\r\n				\r\n				<#if endpoint.config.bearer_token??&&endpoint.config.bearer_token?trim?length gt 0>\r\n				\"authorization\":{\r\n						\"type\":\"Bearer\",\r\n						\"credentials\":\"${endpoint.config.bearer_token}\"\r\n					},\r\n				</#if>\r\n\r\n				\r\n				<#-- params 不为空且类型为 http ，添加 params -->\r\n				<#if endpoint.config.params??&& (endpoint.config.params?size >0) && endpoint.config.protocol == \"http\">\r\n				\"params\":{\r\n					<#list endpoint.config.params?keys as itemKey>\r\n					\"${itemKey}\":[\r\n						<#list endpoint.config.params[itemKey] as pojo>\r\n							\"${pojo}\"\r\n							<#sep>,</#sep>\r\n						</#list>\r\n						]\r\n						<#sep>,</#sep>\r\n					</#list>\r\n				},\r\n				<#elseif endpoint.config.protocol == \"snmp\">\r\n				<#-- 类型是 snmp ，组织 param 数据 ， 原来params弃用，因为 snmp_exporter 不支持其他参数 -->\r\n			   \"params\":{\r\n					\"target\":[ \"${endpoint.config.host}:${endpoint.config.port?c}\" ],\r\n					\"module\":[ \"${endpoint.module.name}\" ]\r\n				},\r\n				</#if>\r\n				\r\n				\"static_configs\": [{\r\n					\"targets\": [<#if endpoint.config.protocol == \"http\">\r\n									\"${endpoint.config.host}:${endpoint.config.port?c}\"\r\n								<#else>\r\n									\"127.0.0.1:19116\"\r\n								</#if>\r\n								],\r\n					\"labels\": {\r\n						\"datacenter\": 	\"${endpoint.dc.name}\",\r\n                        \"datacenter_id\":${endpoint.dc.id?c},\r\n						\r\n						\"project\": 		\"${endpoint.project.name}\",\r\n						\"project_id\":   ${endpoint.project.id?c},\r\n						\r\n						\"asset\": 		\"${endpoint.asset.name}\",\r\n						\"asset_id\":     ${endpoint.asset.id?c},\r\n						\r\n						\"module\": 		\"${endpoint.module.name}\",\r\n						\"module_id\":    ${endpoint.module.id?c},\r\n						\r\n						\"endpoint\":     \"${endpoint.name}\",\r\n						\"endpoint_id\":  ${endpoint.id?c},\r\n						\r\n						<#if endpoint.asset.parent??&&(endpoint.asset.parent?size >0)>\r\n							\"parent_asset\"      :  \"${endpoint.asset.parent.name}\",\r\n							\"parent_asset_id\"   :   ${endpoint.asset.parent.id?c},\r\n						</#if>\r\n\r\n						\"nz_agent_id\":  ${endpoint.promserver.id?c}\r\n												\r\n										\r\n										<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n											,\r\n										</#if>\r\n										<#-- 补充用户自定义 Labels -->\r\n										<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n											<#list endpoint.config.labels?keys as key>\r\n												<#if key != \"datacenter\" && key != \"datacenter_id\" && key != \"project\" && key != \"project_id\" && key != \"asset\" && key != \"asset_id\" && key != \"module\" && key != \"module_id\" && key != \"endpoint\" && key != \"endpoint_id\">\r\n													\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n												</#if>\r\n											 </#list>\r\n										</#if>\r\n					}\r\n				}],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					},\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n				]\r\n				<#if endpoint.relabelConfigListJsonString?default(\"\")?trim?length gt 0>\r\n				,\r\n				\"relabel_configs\": ${endpoint.relabelConfigListJsonString}\r\n				</#if>\r\n			}\r\n			<#sep>,</#sep>\r\n		</#list>\r\n		\r\n		<#-- ping 配置 -->\r\n		\r\n		<#if endpointList??&&(endpointList?size>0)>\r\n		,\r\n		</#if>\r\n		\r\n		<#list assetList as asset>\r\n		{\r\n			\"job_name\": 	\"asset_ping_${asset.id?c}\",\r\n			\"metrics_path\": \"/probe\",\r\n			\"scrape_interval\": 	<#if asset.assetPingInterval?default(\"\")?trim?length gt 0>\r\n									\"${asset.assetPingInterval}s\",\r\n								<#else>\r\n									\"${scrape_interval}s\",\r\n								</#if>\r\n			\"scrape_timeout\": 	<#if asset.scrape_timeout?default(\"\")?trim?length gt 0>\r\n									\"${asset.scrape_timeout}s\",\r\n								<#else>\r\n									<#if scrape_timeout??> \r\n										\"${scrape_timeout}s\",\r\n									<#else>\r\n										\"10s\",\r\n									</#if>\r\n								</#if>\r\n            \"params\":	{\r\n				\"target\":[ \"${asset.manageIp}\" ],\r\n				\"module\":[ \"ping\" ]\r\n			},\r\n			\"static_configs\": [{\r\n				\"targets\": [\"127.0.0.1:19115\"],\r\n				\"labels\": {\r\n					\"datacenter\": 	\"${asset.dc.name}\",\r\n					\"host\": 	  	\"${asset.manageIp}\",\r\n					\"module\":       \"ping\",\r\n					\"source_ip\":    \"${asset.promserver.host}\",\r\n					\"nz_agent_id\":  ${asset.promserver.id?c}\r\n				}\r\n			}],\r\n			\"relabel_configs\": [\r\n				{\r\n					\"regex\": \"job\",\r\n					\"action\": \"labeldrop\"\r\n				},\r\n				{\r\n					\"regex\": \"instance\",\r\n					\"action\": \"labeldrop\"\r\n				}\r\n			],\r\n			\"metric_relabel_configs\": [\r\n			    {\r\n					\"regex\": \"job\",\r\n					\"action\": \"labeldrop\"\r\n				},\r\n				{\r\n					\"regex\": \"instance\",\r\n					\"action\": \"labeldrop\"\r\n				}\r\n			]\r\n		}\r\n		<#sep>,</#sep>\r\n		</#list>\r\n    ]\r\n	<#-- cortex 处理 -->\r\n	,\r\n	\"remote_write\": [\r\n		<#list remoteWriteUrlInfos as remoteConf>\r\n		{	\r\n			\"url\": \"${remoteConf.url}\",\r\n			\"authorization\": {\r\n				\"type\": \"Bearer\",\r\n				\"credentials\": \"${remoteConf.token}\"\r\n			},\r\n			\"queue_config\":{\r\n			    \"capacity\":10,\r\n				\"max_shards\":10\r\n			}\r\n		}\r\n		<#sep>,</#sep>\r\n		</#list>\r\n	]\r\n	<#else>\r\n	<#-- global 配置 -->\r\n	\"scrape_configs\": [\r\n		<#list jobList as jobPojo>\r\n			{\r\n			   \"job_name\": \"${jobPojo.job_name}\",\r\n				<#if jobPojo.isFederate> \r\n				\"honor_labels\": ${jobPojo.honor_labels},\r\n				\"params\": {\r\n					\"match[]\": [\r\n						<#-- 开启联邦 -->\r\n					    <#if jobPojo.fedeEnabled>\r\n							<#if jobPojo.scrapePing> \r\n								\"{job=~\\\"asset_ping_.+\\\",nz_agent_id != \\\"${jobPojo.excludeAgentId}\\\"}\"\r\n							<#else>\r\n								\"{__name__=~\\\".+\\\",nz_agent_id != \\\"${jobPojo.excludeAgentId}\\\"}\"\r\n							</#if>\r\n						<#else>\r\n							<#-- 联邦关闭，抓取所有指标即可 -->\r\n							\"{__name__=~\\\".+\\\",nz_agent_id != \\\"${jobPojo.excludeAgentId}\\\"}\"\r\n						</#if>\r\n					]\r\n				},\r\n				\"authorization\":{\r\n					\"type\":\"Bearer\",\r\n					\"credentials\":\"${jobPojo.token}\"\r\n				},\r\n				</#if>\r\n				\"metrics_path\": <#if jobPojo.metrics_path?default(\"\")?trim?length gt 0>\r\n									\"${jobPojo.metrics_path}\",\r\n								<#else>\r\n									\"/metrics\",\r\n								</#if>\r\n				\"static_configs\":[\r\n					<#list jobPojo.staticConfigList as staticConf >\r\n						{\r\n						  \"targets\": [\r\n								<#list staticConf.targets as targetConf>\r\n										\"${targetConf}\"<#sep>,</#sep>\r\n								</#list>\r\n							]\r\n						<#if staticConf.labels ??&& (staticConf.labels?size >0)>\r\n						   ,\r\n						   \"labels\": {\r\n								<#list staticConf.labels?keys as itemKey>\r\n									\"${itemKey}\":<#if staticConf.labels[itemKey]?default(\"\")?trim?length gt 0>\r\n													\"${staticConf.labels[itemKey]}\"\r\n												  <#else>\"\"</#if><#sep>,</#sep>\r\n								</#list>\r\n							} \r\n						</#if>\r\n						}<#sep>,</#sep>\r\n					</#list>\r\n					],\r\n				\"relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					},\r\n					<#if jobPojo.instanceRelabel> \r\n					{\r\n						\"source_labels\": [\r\n						  \"instance\"\r\n						],\r\n						\"regex\": \"(.+)\",\r\n						\"target_label\": \"target\"\r\n					}\r\n					<#else>\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					</#if>\r\n				],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					},\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n				]\r\n			}<#sep>,</#sep>\r\n		</#list>\r\n		\r\n		<#-- ping 配置 -->\r\n		\r\n		<#if jobList??&&(jobList?size>0)>\r\n		,\r\n		</#if>\r\n		\r\n		<#list assetList as asset>\r\n		{\r\n			\"job_name\": 	\"asset_ping_${asset.id?c}\",\r\n			\"metrics_path\": \"/probe\",\r\n			\"scrape_interval\": 	<#if asset.assetPingInterval?default(\"\")?trim?length gt 0>\r\n									\"${asset.assetPingInterval}s\",\r\n								<#else>\r\n									\"${scrape_interval}s\",\r\n								</#if>\r\n			\"scrape_timeout\": 	<#if asset.scrape_timeout?default(\"\")?trim?length gt 0>\r\n									\"${asset.scrape_timeout}s\",\r\n								<#else>\r\n									<#if scrape_timeout??> \r\n										\"${scrape_timeout}s\",\r\n									<#else>\r\n										\"10s\",\r\n									</#if>\r\n								</#if>\r\n            \"params\":	{\r\n				\"target\":[ \"${asset.manageIp}\" ],\r\n				\"module\":[ \"ping\" ]\r\n			},\r\n			\"static_configs\": [{\r\n				\"targets\": [\"127.0.0.1:19115\"],\r\n				\"labels\": {\r\n					\"datacenter\": 	\"${asset.dc.name}\",\r\n					\"host\": 	  	\"${asset.manageIp}\",\r\n					\"module\":       \"ping\",\r\n					\"source_ip\":    \"${asset.promserver.host}\",\r\n					\"nz_agent_id\":  ${asset.promserver.id?c}\r\n				}\r\n			}],\r\n			\"relabel_configs\": [\r\n				{\r\n					\"regex\": \"job\",\r\n					\"action\": \"labeldrop\"\r\n				},\r\n				{\r\n					\"regex\": \"instance\",\r\n					\"action\": \"labeldrop\"\r\n				}\r\n			],\r\n			\"metric_relabel_configs\": [\r\n			    {\r\n					\"regex\": \"job\",\r\n					\"action\": \"labeldrop\"\r\n				},\r\n				{\r\n					\"regex\": \"instance\",\r\n					\"action\": \"labeldrop\"\r\n				}\r\n			]\r\n		}\r\n		<#sep>,</#sep>\r\n		</#list>\r\n		\r\n		\r\n		<#if ( jobList??&&(jobList?size>0)) ||  assetList??&&(assetList?size>0)>\r\n		,\r\n		</#if>\r\n		\r\n		<#list endpointList as endpoint>\r\n			{\r\n				\"job_name\": ${endpoint.id?c},\r\n				\"metrics_path\": <#if endpoint.config.metrics_path?default(\"\")?trim?length gt 0>\r\n									\"${endpoint.config.metrics_path}\",\r\n								<#else>\r\n									\"/metrics\",\r\n								</#if>\r\n				\"scrape_interval\": 	<#if endpoint.config.scrape_interval?default(\"\")?trim?length gt 0>\r\n										\"${endpoint.config.scrape_interval}s\",\r\n									<#else>\r\n										\"${scrape_interval}s\",\r\n									</#if>\r\n				\"scrape_timeout\": 	<#if endpoint.config.scrape_timeout?default(\"\")?trim?length gt 0>\r\n										\"${endpoint.config.scrape_timeout}s\",\r\n									<#else>\r\n										<#if scrape_timeout??> \r\n											\"${scrape_timeout}s\",\r\n										<#else>\r\n											\"10s\",\r\n										</#if>\r\n									</#if>\r\n\r\n\r\n\r\n				<#if endpoint.config.basic_auth??&& (endpoint.config.basic_auth?size >0)>\r\n					<#if endpoint.config.basic_auth.username?default(\"\")?trim?length gt 0 && endpoint.config.basic_auth.password?default(\"\")?trim?length gt 0>\r\n					\"basic_auth\":{\r\n						\"username\": \"${endpoint.config.basic_auth.username}\",\r\n						\"password\": \"${endpoint.config.basic_auth.password}\"\r\n						},\r\n					</#if>\r\n				</#if>\r\n				\r\n				\r\n				<#if endpoint.config.bearer_token??&&endpoint.config.bearer_token?trim?length gt 0>\r\n				\"authorization\":{\r\n						\"type\":\"Bearer\",\r\n						\"credentials\":\"${endpoint.config.bearer_token}\"\r\n					},\r\n				</#if>\r\n\r\n				\r\n				<#-- params 不为空且类型为 http ，添加 params -->\r\n				<#if endpoint.config.params??&& (endpoint.config.params?size >0) && endpoint.config.protocol == \"http\">\r\n				\"params\":{\r\n					<#list endpoint.config.params?keys as itemKey>\r\n					\"${itemKey}\":[\r\n						<#list endpoint.config.params[itemKey] as pojo>\r\n							\"${pojo}\"\r\n							<#sep>,</#sep>\r\n						</#list>\r\n						]\r\n						<#sep>,</#sep>\r\n					</#list>\r\n				},\r\n				<#elseif endpoint.config.protocol == \"snmp\">\r\n				<#-- 类型是 snmp ，组织 param 数据 ， 原来params弃用，因为 snmp_exporter 不支持其他参数 -->\r\n			   \"params\":{\r\n					\"target\":[ \"${endpoint.config.host}:${endpoint.config.port?c}\" ],\r\n					\"module\":[ \"${endpoint.module.name}\" ]\r\n				},\r\n				</#if>\r\n				\r\n				\"static_configs\": [{\r\n					\"targets\": [<#if endpoint.config.protocol == \"http\">\r\n									\"${endpoint.config.host}:${endpoint.config.port?c}\"\r\n								<#else>\r\n									\"127.0.0.1:19116\"\r\n								</#if>\r\n								],\r\n					\"labels\": {\r\n						\"datacenter\": 	\"${endpoint.dc.name}\",\r\n                        \"datacenter_id\":${endpoint.dc.id?c},\r\n						\r\n						\"project\": 		\"${endpoint.project.name}\",\r\n						\"project_id\":   ${endpoint.project.id?c},\r\n						\r\n						\"asset\": 		\"${endpoint.asset.name}\",\r\n						\"asset_id\":     ${endpoint.asset.id?c},\r\n						\r\n						\"module\": 		\"${endpoint.module.name}\",\r\n						\"module_id\":    ${endpoint.module.id?c},\r\n						\r\n						\"endpoint\":     \"${endpoint.name}\",\r\n						\"endpoint_id\":  ${endpoint.id?c},\r\n						\r\n						<#if endpoint.asset.parent??&&(endpoint.asset.parent?size >0)>\r\n							\"parent_asset\"      :  \"${endpoint.asset.parent.name}\",\r\n							\"parent_asset_id\"   :   ${endpoint.asset.parent.id?c},\r\n						</#if>\r\n						\r\n						\"nz_agent_id\":  ${endpoint.promserver.id?c}\r\n												\r\n										\r\n										<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n											,\r\n										</#if>\r\n										<#-- 补充用户自定义 Labels -->\r\n										<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n											<#list endpoint.config.labels?keys as key>\r\n												<#if key != \"datacenter\" && key != \"datacenter_id\" && key != \"project\" && key != \"project_id\" && key != \"asset\" && key != \"asset_id\" && key != \"module\" && key != \"module_id\" && key != \"endpoint\" && key != \"endpoint_id\">\r\n													\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n												</#if>\r\n											 </#list>\r\n										</#if>\r\n					}\r\n				}],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					},\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n				]\r\n				<#if endpoint.relabelConfigListJsonString?default(\"\")?trim?length gt 0>\r\n				,\r\n				\"relabel_configs\": ${endpoint.relabelConfigListJsonString}\r\n				</#if>\r\n			}\r\n			<#sep>,</#sep>\r\n		</#list>\r\n	\r\n	]\r\n	\r\n	<#-- cortex 处理 -->\r\n	,\r\n	\"remote_write\": [\r\n		<#list remoteWriteUrlInfos as remoteConf>\r\n		{	\r\n			\"url\": \"${remoteConf.url}\",\r\n			\"authorization\": {\r\n				\"type\": \"Bearer\",\r\n				\"credentials\": \"${remoteConf.token}\"\r\n			},\r\n			\"queue_config\":{\r\n			    \"capacity\":10,\r\n				\"max_shards\":10\r\n			}\r\n		}\r\n		<#sep>,</#sep>\r\n		</#list>\r\n	]	\r\n	</#if>\r\n}', 1, 'prometheus config文件模板');
